/**
 * Popup — base modal dialog: dimmed overlay that blocks input, a panel with a title, a body line
 * and one button. One subclass and one prefab per kind (ADR-0007): PopupLevelComplete,
 * PopupSettings. Game instantiates the kind's prefab from resources/prefabs into the `popup`
 * slot when needed, calls init(frames) then show(opts); hide() plays nothing and destroys the
 * node, so every appearance is a fresh instance and nothing modal lives in the scene.
 *
 * The prefabs are generated by tools/gen-popup-prefab.js with the art wired and then edited in
 * Creator. Adding a popup component to a bare node runs `populate`, which creates the missing
 * parts at the data/Layout defaults (editor on add, or runtime when a prefab is missing).
 * Depends on UiKit, data/Layout, data/Palette, data/Timing.
 */
const UiKit = require('UiKit');
const { LAYOUT } = require('Layout');
const { UI } = require('Palette');
const { TIMING, EASING } = require('Timing');

function frameProp(what) {
  return {
    default: null,
    type: cc.SpriteFrame,
    tooltip: what,
    notify() {
      this._applyFrames(null);
    },
  };
}

const Popup = cc.Class({
  extends: cc.Component,

  editor: CC_EDITOR && { executeInEditMode: true },

  properties: {
    panelFrame: frameProp('Panel.png: the dialog panel (two layers, since the texture is translucent)'),
    overlayFrame: frameProp('Block_back.png: flat texture tinted as the dimming overlay'),
    buttonFrame: frameProp('Button.png: the action button'),
    overlay: { default: null, type: cc.Node, tooltip: 'Full-screen dimming sprite (created by populate when empty)' },
    panel: { default: null, type: cc.Node, tooltip: 'Dialog panel, scales in on show (created by populate when empty)' },
    titleLabel: { default: null, type: cc.Label, tooltip: 'Title label on the panel' },
    bodyLabel: { default: null, type: cc.Label, tooltip: 'Body line on the panel' },
    button: { default: null, type: cc.Node, tooltip: 'Action button node with a cc.Button' },
    buttonLabel: { default: null, type: cc.Label, tooltip: 'Label inside the action button' },
  },

  onLoad() {
    if (CC_EDITOR) {
      this.populate(null);
    }
  },

  /** Wires the popup for play. @param {object} frames sprite frames by name (fallbacks) */
  init(frames) {
    this.populate(frames);
    this.button.on('click', () => this._onButton(), this);
    this._callback = null;
  },

  /** Creates whatever is unassigned at the data/Layout defaults and applies textures. */
  populate(frames) {
    UiKit.stretch(this.node, true, true, true, true);
    if (!this.node.getComponent(cc.BlockInputEvents)) {
      this.node.addComponent(cc.BlockInputEvents);
    }
    const panelFrame = this.panelFrame || (frames && frames.Panel);
    if (!this.overlay) {
      this.overlay = UiKit.sprite(this.node, this.overlayFrame || (frames && frames.Block_back), this.node.width, this.node.height, 'overlay');
      UiKit.stretch(this.overlay, true, true, true, true);
      this.overlay.color = UiKit.color(UI.OVERLAY);
      this.overlay.opacity = LAYOUT.OVERLAY_OPACITY;
    }
    if (!this.panel) {
      this.panel = UiKit.sliced(this.node, panelFrame, LAYOUT.POPUP_WIDTH, LAYOUT.POPUP_HEIGHT, null, 'panel', LAYOUT.PANEL_INSET);
      // The Panel texture is translucent by design; a second layer makes the dialog nearly opaque
      // so the board underneath does not show through the text. First child, so it draws behind.
      UiKit.sliced(this.panel, panelFrame, LAYOUT.POPUP_WIDTH, LAYOUT.POPUP_HEIGHT, null, 'backing', LAYOUT.PANEL_INSET);
    }
    if (!this.titleLabel) {
      const title = UiKit.label(this.panel, 'Title', LAYOUT.POPUP_TITLE_FONT, UI.PANEL_TITLE, 'title');
      title.y = LAYOUT.POPUP_TITLE_Y;
      this.titleLabel = title.getComponent(cc.Label);
    }
    if (!this.bodyLabel) {
      const body = UiKit.label(this.panel, 'Body text', LAYOUT.POPUP_BODY_FONT, UI.POPUP_TEXT, 'body');
      body.y = LAYOUT.POPUP_BODY_Y;
      this.bodyLabel = body.getComponent(cc.Label);
    }
    if (!this.button) {
      this.button = UiKit.button(this.panel, this.buttonFrame || (frames && frames.Button), LAYOUT.BUTTON_WIDTH, LAYOUT.BUTTON_HEIGHT, 'OK', LAYOUT.BUTTON_FONT, UI.BUTTON_TEXT, null, 'button');
      this.button.y = LAYOUT.POPUP_BUTTON_Y;
    }
    if (!this.button.getComponent(cc.Button)) {
      const b = this.button.addComponent(cc.Button);
      b.transition = cc.Button.Transition.SCALE;
      b.zoomScale = 0.92;
    }
    if (!this.buttonLabel) {
      const text = this.button.getChildByName('text') || UiKit.label(this.button, 'OK', LAYOUT.BUTTON_FONT, UI.BUTTON_TEXT, 'text');
      this.buttonLabel = text.getComponent(cc.Label);
    }
    this._applyFrames(frames);
  },

  _applyFrames(frames) {
    const panelFrame = this.panelFrame || (frames && frames.Panel);
    UiKit.setFrame(this.overlay, this.overlayFrame || (frames && frames.Block_back), null, !!this.overlayFrame);
    UiKit.setFrame(this.panel, panelFrame, LAYOUT.PANEL_INSET, !!this.panelFrame);
    UiKit.setFrame(this.panel && this.panel.getChildByName('backing'), panelFrame, LAYOUT.PANEL_INSET, !!this.panelFrame);
    UiKit.setFrame(this.button, this.buttonFrame || (frames && frames.Button), null, !!this.buttonFrame);
  },

  /**
   * Shows the dialog. Subclasses map their own options onto these; texts left undefined keep
   * what the prefab was authored with.
   * @param {{ title?: string, body?: string, button?: string, onButton?: Function }} opts
   */
  show(opts) {
    opts = opts || {};
    if (opts.title !== undefined) {
      this.titleLabel.string = opts.title;
    }
    if (opts.body !== undefined) {
      this.bodyLabel.string = opts.body;
    }
    if (opts.button !== undefined) {
      this.buttonLabel.string = opts.button;
    }
    this._callback = opts.onButton || null;
    this.node.active = true;
    this.overlay.opacity = 0;
    this.panel.scale = 0.8;
    cc.tween(this.overlay).to(TIMING.POPUP, { opacity: LAYOUT.OVERLAY_OPACITY }).start();
    cc.tween(this.panel).to(TIMING.POPUP, { scale: 1 }, { easing: EASING.POPUP }).start();
  },

  /** Closes and destroys the instance. */
  hide() {
    cc.Tween.stopAllByTarget(this.overlay);
    cc.Tween.stopAllByTarget(this.panel);
    this.node.destroy();
  },

  // A plain method, not an ES getter: cc.Class reads every key of this object while defining
  // the class, which would run a getter before any node exists.
  isShowing() {
    return !!this.node && this.node.isValid && this.node.active;
  },

  _onButton() {
    const cb = this._callback;
    this.hide();
    if (cb) {
      cb();
    }
  },
});

module.exports = Popup;
